// Draw marbles (spherical pieces)
function drawMarble(x, y, size, color) {
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();

    // Add some marbling effect
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Add a subtle highlight
    ctx.fillStyle = '#F0F0F0';
    ctx.beginPath();
    ctx.arc(x - 2, y - 2, size / 8, 0, Math.PI * 2);
    ctx.fill();
}

