// Function to draw spiral segment
function drawSpiralSegment(radius, angle, color) {
  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.lineTo(
    centerX + Math.cos(angle) * radius,
    centerY + Math.sin(angle) * radius
  );
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.stroke();
}

// Draw spiral
let angle = 0;
let radius = 0;
const spiralLength = 150; // Adjust this value to change spiral length

while (radius < spiralLength) {
  const segmentLength = 5; // Adjust this value to change segment size
  for (let i = 0; i < segmentLength; i++) {
    const segmentAngle = angle + i * 0.1; // Add some randomness
    drawSpiralSegment(radius, segmentAngle, colors[Math.floor(i / 5)]);
  }
  radius += 5;
  angle += 0.1;
}

